/*
 * punku-chat loader for the swarovski-widget branch.
 * The widget now comes from the v1 release channel, so this page gets every
 * release like all other embeds. Fallback: jsDelivr @v1 (the same release).
 */
(function () {
  if (window.customElements && window.customElements.get("punku-chat")) return;
  var SOURCES = [
    "https://cdn.punku.ai/chat/v1/bundle.min.js",
    "https://cdn.jsdelivr.net/gh/PUNKU-AI/punku-embedded-chat@v1/dist/build/static/js/bundle.min.js"
  ];
  function load(i) {
    if (i >= SOURCES.length) return;
    var script = document.createElement("script");
    script.src = SOURCES[i];
    script.async = true;
    script.onerror = function () { load(i + 1); };
    (document.head || document.documentElement).appendChild(script);
  }
  load(0);
})();
